-- ============================================================================
-- 思弈阁（B 仓）MySQL 8 全量建表脚本 —— 当前项目状态（42 张表）
--
-- 来源：server/src/main/resources/schema-*.sql（H2 方言）机械翻译 + 人工校对。
-- 翻译规则：
--   bigint generated by default as identity -> bigint not null auto_increment
--   clob -> longtext ; boolean -> tinyint(1)
--   create [unique] index 语句 -> 表内 KEY / UNIQUE KEY
--     （MySQL 8 的 CREATE INDEX 没有 IF NOT EXISTS，挪进建表语句才可重复执行）
--   alter table ... add column if not exists -> 直接折进建表语句
--     （MySQL 8 的 ADD COLUMN 同样没有 IF NOT EXISTS）
--   H2 行内注释（-- xxx）已去掉；列语义仍以 schema-*.sql 与 SPEC 为准
--
-- 用法：空库执行一次；全部 if not exists，重复执行安全。
--   docker cp schema-mysql-full.sql siyige-mysql:/tmp/s.sql
--   docker exec siyige-mysql sh -c 'mysql -uroot -p*** siyige < /tmp/s.sql'
-- ============================================================================

set names utf8mb4;

-- ---------- sy_user（来自 schema.sql） ----------
create table if not exists sy_user (

  id         varchar(32) primary key,
  name       varchar(64),
  created_at timestamp default current_timestamp,
  account varchar(64),
  password_hash varchar(255),
  status tinyint default 1,
  pwd_changed_at timestamp,
  is_bot tinyint not null default 0,
  unique key ux_user_account (account),
  key ix_user_created (created_at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

-- ---------- sy_topic（来自 schema.sql） ----------
create table if not exists sy_topic (

  id           varchar(32) primary key,
  title        varchar(200),
  cat          varchar(32),
  diff         varchar(16),
  source       varchar(16) default 'official',   
  plays        int default 0,
  mod_status   varchar(16) default 'PASS',       
  mod_reason   varchar(300),
  mod_at       timestamp,
  title_hash   varchar(64)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

-- ---------- sy_match（来自 schema.sql） ----------
create table if not exists sy_match (

  id           varchar(40) primary key,
  user_id      varchar(32),
  topic_id     varchar(32),
  topic_title  varchar(200),
  mode         varchar(16),        
  my_seats     varchar(40),        
  step         int default 0,
  status       varchar(16),        
  deadline_at  timestamp,
  started_at   timestamp default current_timestamp,
  finished_at  timestamp,
  total_score  int,
  turn_sec int default 0,
  pace varchar(8) default 'normal',
  extend_count int default 0,
  warned boolean default false,
  difficulty varchar(8) default 'pro',
  phase varchar(8) default 'STEP',
  buzz_seat varchar(4),
  kind varchar(8) default 'solo',
  query_rounds int default 2,
  free_rounds int default 4,
  token_base bigint default 0,
  bill_tokens bigint default 0,
  own_key boolean default false,
  tier varchar(16) default 'PRO',
  payer_user_id varchar(32),
  skipped_step int default -1,
  last_skip_at bigint default 0,
  key ix_match_started (started_at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

-- ---------- sy_turn（来自 schema.sql） ----------
create table if not exists sy_turn (

  id         bigint not null auto_increment primary key,
  match_id   varchar(40),
  step       int,
  seat       varchar(4),
  seg        varchar(16),
  content    varchar(4000),
  status     varchar(16),          
  input_type varchar(16),          
  created_at timestamp default current_timestamp,
  key ix_turn (match_id, step),
  key ix_turn_created (created_at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

-- ---------- sy_audit（来自 schema.sql） ----------
create table if not exists sy_audit (

