  match_id  varchar(40),
  step      int,
  type      varchar(16),
  hit       tinyint(1),              
  created_at timestamp default current_timestamp
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

-- ---------- sy_brief（来自 schema.sql） ----------
create table if not exists sy_brief (

