-- ---------- sy_post（来自 schema-community.sql） ----------
create table if not exists sy_post (

  id              bigint not null auto_increment primary key,
  author_id       varchar(32)  not null,              
  type            varchar(8)   not null,              
  title           varchar(120) not null,
  body            longtext         not null,              
  excerpt         varchar(220) not null,              
  topic_id        varchar(32)  null,                  
  comment_count   int          not null default 0,    
  like_count      int          not null default 0,
  view_count      int          not null default 0,
  hot_score       double       not null default 0,    
  last_comment_at timestamp    null,
  status          tinyint      not null default 1,    
  created_at      timestamp    not null default current_timestamp,
  updated_at      timestamp    null,
  key ix_post_new (status, created_at),
  key ix_post_comments (status, comment_count),
  key ix_post_likes (status, like_count),
  key ix_post_hot (status, hot_score),
  key ix_post_type (status, type, created_at),
  key ix_post_topic (topic_id, status, created_at),
  key ix_post_author (author_id, created_at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

-- ---------- sy_post_comment（来自 schema-community.sql） ----------
create table if not exists sy_post_comment (

  id                      bigint not null auto_increment primary key,
  post_id                 bigint        not null,
  user_id                 varchar(32)   not null,
  root_id                 bigint        null,          
  reply_object_type       varchar(8)    not null default 'POST',  
  reply_object_comment_id bigint        null,
  reply_object_user_id    varchar(32)   null,
  body                    varchar(1000) not null,
  like_count              int           not null default 0,
  status                  tinyint       not null default 1,
  created_at              timestamp     not null default current_timestamp,
  key ix_cmt_post (post_id, status, root_id, created_at),
  key ix_cmt_root (root_id, status, created_at),
  key ix_cmt_user (user_id, created_at),
  key ix_comment_status (status, created_at),
  key ix_comment_author (user_id, created_at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

