  updated_by varchar(64),
  updated_at timestamp    not null default current_timestamp
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

-- ---------- sy_config_log（来自 schema-config.sql） ----------
create table if not exists sy_config_log (

  id         bigint not null auto_increment primary key,
  k          varchar(64)  not null,
  old_v      varchar(500),
  new_v      varchar(500) not null,
  operator   varchar(64),
  created_at timestamp    not null default current_timestamp,
  key ix_config_log_k (k, created_at)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;

-- ---------- sy_sensitive_word（来自 schema-word.sql） ----------
create table if not exists sy_sensitive_word (

  id         bigint not null auto_increment primary key,
  word       varchar(64) not null,           
  word_key   varchar(64) not null,           
  scope      varchar(16) not null,           
  enabled    tinyint     not null default 1, 
  created_by varchar(64),
  created_at timestamp   not null default current_timestamp,
  updated_at timestamp   not null default current_timestamp,
  unique key ux_word_scope_key (scope, word_key),
  key ix_word_scope (scope, enabled)
) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;
